import type { ClientRequest } from "http";
import type { ProxyOptions } from "vite";
import type { Credential } from "../servicenow/types";

export const DEFAULT_PROXY_PATHS = [
  "/api",
  "/amb",
  "/scripts/",
  "/images/@servicenow/",
  "/uxasset/externals",
  "/$uxappimmutables.do",
  "/uxta",
];

export async function createViteProxy(
  credential: Credential | undefined,
  proxyPaths: string[] = DEFAULT_PROXY_PATHS,
): Promise<Record<string, ProxyOptions>> {
  const proxy: Record<string, ProxyOptions> = {};

  if (
    !credential ||
    typeof credential.getUrl !== "function" ||
    typeof credential.getHeaders !== "function"
  ) {
    return proxy;
  }

  const authHeaders = await credential.getHeaders();
  const proxyTarget = credential.getUrl().href.replace(/\/$/, "");

  for (const proxyPath of proxyPaths) {
    proxy[proxyPath] = {
      target: proxyTarget,
      changeOrigin: true,
      ...(proxyPath === "/amb" ? { ws: true } : {}),
      configure: (proxyServer) => {
        proxyServer.on("proxyReq", (proxyReq: ClientRequest) => {
          for (const [key, value] of Object.entries(authHeaders)) {
            proxyReq.setHeader(key, value);
          }
        });
      },
    };
  }

  return proxy;
}
